-- EduClass Fusion database update. Paste the whole file into the Supabase SQL editor and run it once.
-- Contains: 20260101002400_results_guard.sql, 20260101002500_question_bank.sql, 20260101002600_exam_logistics.sql, 20260101002700_moderation.sql, 20260101002800_report_cards_plus.sql
-- Safe to run again (every part is idempotent). Generated by scripts/bundle-update.mjs.

-- ===== 20260101002400_results_guard.sql =====
-- =========================================================================
-- EduClass Fusion: lock down report cards.
--  Before this, any staff account (gate officer, cashier, nurse, any teacher)
--  could rewrite a card's grades, average and position, write the principal's
--  comment, or delete cards, published ones included, by calling the database
--  API directly. Now:
--   * school admins can do everything (publishing still goes through them);
--   * the form teacher of the student's class can compile cards and write the
--     form teacher's comment, but cannot touch published cards;
--   * nobody else can change report cards;
--   * only school admins can delete them.
-- Apply AFTER 20260101002300. Idempotent.
-- =========================================================================

drop policy if exists report_cards_write on public.report_cards;
drop policy if exists report_cards_insert on public.report_cards;
create policy report_cards_insert on public.report_cards for insert
  with check (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists report_cards_update on public.report_cards;
create policy report_cards_update on public.report_cards for update
  using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists report_cards_delete on public.report_cards;
create policy report_cards_delete on public.report_cards for delete
  using (tenant_id = public.my_tenant_id() and public.is_school_admin());

create or replace function public.report_cards_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_school_admin() then return new; end if;
  if (tg_op = 'INSERT' and new.status <> 'draft') or
     (tg_op = 'UPDATE' and new.status is distinct from old.status) then
    raise exception 'only school admins can approve or publish results';
  end if;
  if tg_op = 'UPDATE' and old.status = 'published' then
    raise exception 'only school admins can change a published report card';
  end if;
  if (tg_op = 'INSERT' and new.principal_comment is not null) or
     (tg_op = 'UPDATE' and new.principal_comment is distinct from old.principal_comment) then
    raise exception 'only school admins can write the principal''s comment';
  end if;
  -- Everything else (compiling, the form teacher's comment): the form teacher
  -- of the class the student is in now, for a card filed under that class.
  if not exists (
    select 1 from public.students s join public.class_groups g on g.id = s.class_group_id
    where s.id = new.student_id and g.tenant_id = new.tenant_id
      and g.form_teacher_id = auth.uid() and new.class_group_id = g.id
  ) then
    raise exception 'only the form teacher or a school admin can change this report card';
  end if;
  return new;
end $$;
drop trigger if exists report_cards_guard on public.report_cards;
create trigger report_cards_guard before insert or update on public.report_cards
  for each row execute function public.report_cards_guard();

-- ===== 20260101002500_question_bank.sql =====
-- =========================================================================
-- EduClass Fusion: question bank, past questions and practice.
--  * Two more exam question types: maths input and drag-and-drop.
--  * question_bank: reusable questions tagged by subject, level, topic,
--    difficulty, Bloom's level and (for past questions) exam body and year.
--    Answer keys stay staff-only, like exam_questions.
--  * Exams copy questions from the bank (bank_question_id keeps the link, and
--    topic / difficulty / Bloom's are copied for item analysis).
--  * practice_sessions: students drill bank questions marked for practice and
--    get instant feedback. Written only by the API (service role).
-- Apply AFTER 20260101002400. Idempotent.
-- =========================================================================

alter table public.exam_questions drop constraint if exists exam_questions_type_check;
alter table public.exam_questions add constraint exam_questions_type_check check (type in (
  'mcq_single','mcq_multi','true_false','short_answer','numeric','fill_blanks',
  'matching','ordering','hotspot','essay','code','file_upload','math','drag_drop'));

create table if not exists public.question_bank (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  created_by    uuid references public.users(id) on delete set null,
  subject_id    uuid references public.subjects(id) on delete set null,
  level         text,                                   -- JSS1, SS2, Year 9, Grade 10 …
  topic         text,
  difficulty    text check (difficulty in ('easy','medium','hard')),
  bloom         text check (bloom in ('remember','understand','apply','analyse','evaluate','create')),
  exam_body     text,                                   -- WAEC, NECO, JAMB, BECE, IGCSE, A Level, NCEE, SAT …
  exam_year     int check (exam_year between 1950 and 2100),
  type          text not null check (type in (
                  'mcq_single','mcq_multi','true_false','short_answer','numeric','fill_blanks',
                  'matching','ordering','hotspot','essay','code','file_upload','math','drag_drop')),
  prompt        text not null,
  media_url     text,
  points        numeric not null default 1 check (points >= 0),
  data          jsonb not null default '{}'::jsonb,
  answer        jsonb not null default '{}'::jsonb,
  explanation   text,                                   -- shown after a practice answer
  practice      boolean not null default false,         -- students may drill it (they will see the answer)
  times_used    int not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists question_bank_lookup on public.question_bank(tenant_id, subject_id, topic);
create index if not exists question_bank_past on public.question_bank(tenant_id, exam_body, exam_year);

alter table public.exam_questions add column if not exists bank_question_id uuid references public.question_bank(id) on delete set null;
alter table public.exam_questions add column if not exists topic text;
alter table public.exam_questions add column if not exists difficulty text;
alter table public.exam_questions add column if not exists bloom text;

alter table public.question_bank enable row level security;
drop policy if exists question_bank_read on public.question_bank;
create policy question_bank_read on public.question_bank for select using (
  tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists question_bank_insert on public.question_bank;
create policy question_bank_insert on public.question_bank for insert with check (
  tenant_id = public.my_tenant_id() and public.is_staff() and created_by = auth.uid());
drop policy if exists question_bank_change on public.question_bank;
create policy question_bank_change on public.question_bank for update using (
  tenant_id = public.my_tenant_id() and (created_by = auth.uid() or public.is_school_admin())
) with check (tenant_id = public.my_tenant_id());
drop policy if exists question_bank_delete on public.question_bank;
create policy question_bank_delete on public.question_bank for delete using (
  tenant_id = public.my_tenant_id() and (created_by = auth.uid() or public.is_school_admin()));

create table if not exists public.practice_sessions (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  student_user_id  uuid not null references public.users(id) on delete cascade,
  filters          jsonb not null default '{}'::jsonb,   -- subject, exam body, year, topic, difficulty
  question_ids     jsonb not null default '[]'::jsonb,
  option_orders    jsonb not null default '{}'::jsonb,
  answers          jsonb not null default '{}'::jsonb,
  marks            jsonb not null default '{}'::jsonb,
  score            numeric not null default 0,
  max_score        numeric not null default 0,
  started_at       timestamptz not null default now(),
  finished_at      timestamptz
);
create index if not exists practice_sessions_student on public.practice_sessions(student_user_id, started_at desc);

alter table public.practice_sessions enable row level security;
drop policy if exists practice_sessions_read on public.practice_sessions;
create policy practice_sessions_read on public.practice_sessions for select using (
  tenant_id = public.my_tenant_id() and (student_user_id = auth.uid() or public.is_staff()));

-- ===== 20260101002600_exam_logistics.sql =====
-- =========================================================================
-- EduClass Fusion: exam logistics.
--  * exam_halls: rooms with a capacity and a rows × columns layout.
--  * exam_series: one exam period (e.g. first-term examinations) with its
--    dates, daily sessions and planning rules.
--  * exam_papers: what is sat, by which classes, and when. A paper can link
--    to a CBT exam.
--  * exam_seats: seating plan per paper (hall, row, column, label).
--  * exam_invigilations: who supervises which hall in which session.
-- Admins plan; staff read everything; students read their own published
-- timetable and seats.
-- Apply AFTER 20260101002500. Idempotent.
-- =========================================================================

create table if not exists public.exam_halls (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  name        text not null,
  capacity    int not null check (capacity between 1 and 5000),
  rows        int not null default 0 check (rows between 0 and 200),
  cols        int not null default 0 check (cols between 0 and 200),
  notes       text,
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  unique (tenant_id, name)
);

create table if not exists public.exam_series (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  term_id            uuid references public.terms(id) on delete set null,
  name               text not null,
  starts_on          date not null,
  ends_on            date not null,
  -- [{ "label": "Morning", "start": "09:00", "minutes": 150 }, …]
  sessions           jsonb not null default '[{"label":"Morning","start":"09:00","minutes":150},{"label":"Afternoon","start":"12:30","minutes":120}]'::jsonb,
  skip_dates         jsonb not null default '[]'::jsonb,
  max_per_day        int not null default 2 check (max_per_day between 1 and 6),
  invigilator_ratio  int not null default 30 check (invigilator_ratio between 5 and 200),
  spacing            text not null default 'every_seat' check (spacing in ('every_seat','alternate')),
  status             text not null default 'draft' check (status in ('draft','published')),
  created_by         uuid references public.users(id) on delete set null,
  created_at         timestamptz not null default now(),
  check (ends_on >= starts_on)
);

create table if not exists public.exam_papers (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  series_id         uuid not null references public.exam_series(id) on delete cascade,
  subject_id        uuid references public.subjects(id) on delete set null,
  title             text not null,
  class_group_ids   uuid[] not null default '{}',
  duration_minutes  int not null default 120 check (duration_minutes between 5 and 600),
  slot_date         date,
  slot_session      int,
  locked            boolean not null default false,   -- keep this slot when regenerating
  exam_id           uuid references public.exams(id) on delete set null,
  created_at        timestamptz not null default now()
);
create index if not exists exam_papers_series on public.exam_papers(series_id, slot_date, slot_session);

create table if not exists public.exam_seats (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  series_id   uuid not null references public.exam_series(id) on delete cascade,
  paper_id    uuid not null references public.exam_papers(id) on delete cascade,
  hall_id     uuid not null references public.exam_halls(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  row         int not null,
  col         int not null,
  label       text not null,
  unique (paper_id, student_id)
);
create index if not exists exam_seats_series on public.exam_seats(series_id, hall_id);
create index if not exists exam_seats_student on public.exam_seats(student_id);

create table if not exists public.exam_invigilations (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  series_id      uuid not null references public.exam_series(id) on delete cascade,
  slot_date      date not null,
  slot_session   int not null,
  hall_id        uuid not null references public.exam_halls(id) on delete cascade,
  staff_user_id  uuid not null references public.users(id) on delete cascade,
  chief          boolean not null default false,
  unique (series_id, slot_date, slot_session, staff_user_id)
);

alter table public.exam_halls          enable row level security;
alter table public.exam_series         enable row level security;
alter table public.exam_papers         enable row level security;
alter table public.exam_seats          enable row level security;
alter table public.exam_invigilations  enable row level security;

-- Staff read everything in their school; only school admins change plans.
do $$
declare t text;
begin
  foreach t in array array['exam_halls','exam_series','exam_papers','exam_seats','exam_invigilations'] loop
    execute format('drop policy if exists %I on public.%I', t || '_staff_read', t);
    execute format('create policy %I on public.%I for select using (tenant_id = public.my_tenant_id() and public.is_staff())', t || '_staff_read', t);
    execute format('drop policy if exists %I on public.%I', t || '_admin_write', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_school_admin()) with check (tenant_id = public.my_tenant_id() and public.is_school_admin())', t || '_admin_write', t);
  end loop;
end $$;

-- Students (and their guardians) see published papers for their class and their own seats.
drop policy if exists exam_series_student_read on public.exam_series;
create policy exam_series_student_read on public.exam_series for select using (
  tenant_id = public.my_tenant_id() and status = 'published');
drop policy if exists exam_papers_student_read on public.exam_papers;
create policy exam_papers_student_read on public.exam_papers for select using (
  tenant_id = public.my_tenant_id()
  and exists (select 1 from public.exam_series s where s.id = exam_papers.series_id and s.status = 'published')
  and exists (select 1 from public.students st where st.class_group_id = any(exam_papers.class_group_ids)
              and (st.user_id = auth.uid() or public.is_guardian_of(st.id))));
drop policy if exists exam_seats_student_read on public.exam_seats;
create policy exam_seats_student_read on public.exam_seats for select using (
  tenant_id = public.my_tenant_id()
  and exists (select 1 from public.exam_series s where s.id = exam_seats.series_id and s.status = 'published')
  and exists (select 1 from public.students st where st.id = exam_seats.student_id and (st.user_id = auth.uid() or public.is_guardian_of(st.id))));
drop policy if exists exam_halls_student_read on public.exam_halls;
create policy exam_halls_student_read on public.exam_halls for select using (
  tenant_id = public.my_tenant_id()
  and exists (select 1 from public.exam_seats x join public.students st on st.id = x.student_id
              where x.hall_id = exam_halls.id and (st.user_id = auth.uid() or public.is_guardian_of(st.id))));

-- ===== 20260101002700_moderation.sql =====
-- =========================================================================
-- EduClass Fusion: score moderation (teacher → head of department → principal).
--  * departments get a head (HOD); subjects belong to a department.
--    Departments were writable by every account in the school (students
--    included); now only school admins change them, since the head approves
--    scores.
--  * score_sheets: one row per term × class × subject with its approval
--    status. Changes go through moderate_score_sheet(), which checks who may
--    do what and logs every step in score_sheet_events.
--  * When a school turns moderation on (tenant_settings.require_moderation),
--    scores on a submitted or approved sheet are locked for everyone except
--    school admins, until the sheet is returned for correction.
-- Apply AFTER 20260101002600. Idempotent.
-- =========================================================================

alter table public.departments add column if not exists head_user_id uuid references public.users(id) on delete set null;
alter table public.subjects add column if not exists department_id uuid references public.departments(id) on delete set null;
alter table public.tenant_settings add column if not exists require_moderation boolean not null default false;

drop policy if exists departments_tenant on public.departments;
drop policy if exists departments_read on public.departments;
create policy departments_read on public.departments for select using (tenant_id = public.my_tenant_id());
drop policy if exists departments_write on public.departments;
create policy departments_write on public.departments for all using (
  tenant_id = public.my_tenant_id() and public.is_school_admin()
) with check (tenant_id = public.my_tenant_id() and public.is_school_admin());

create table if not exists public.score_sheets (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  term_id         uuid not null references public.terms(id) on delete cascade,
  class_group_id  uuid not null references public.class_groups(id) on delete cascade,
  subject_id      uuid not null references public.subjects(id) on delete cascade,
  status          text not null default 'draft' check (status in ('draft','submitted','hod_approved','approved','returned')),
  submitted_by    uuid references public.users(id) on delete set null,
  submitted_at    timestamptz,
  hod_by          uuid references public.users(id) on delete set null,
  hod_at          timestamptz,
  approved_by     uuid references public.users(id) on delete set null,
  approved_at     timestamptz,
  note            text,                                  -- latest return note
  updated_at      timestamptz not null default now(),
  unique (term_id, class_group_id, subject_id)
);
create table if not exists public.score_sheet_events (
  id         uuid primary key default gen_random_uuid(),
  sheet_id   uuid not null references public.score_sheets(id) on delete cascade,
  action     text not null,
  actor_id   uuid references public.users(id) on delete set null,
  note       text,
  at         timestamptz not null default now()
);
create index if not exists score_sheet_events_sheet on public.score_sheet_events(sheet_id, at);

alter table public.score_sheets enable row level security;
alter table public.score_sheet_events enable row level security;
drop policy if exists score_sheets_read on public.score_sheets;
create policy score_sheets_read on public.score_sheets for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists score_sheet_events_read on public.score_sheet_events;
create policy score_sheet_events_read on public.score_sheet_events for select using (
  exists (select 1 from public.score_sheets s where s.id = score_sheet_events.sheet_id and s.tenant_id = public.my_tenant_id() and public.is_staff()));
-- No insert/update/delete policies: all writes go through moderate_score_sheet().

/** Is the caller the head of the department this subject belongs to? */
create or replace function public.is_hod_of_subject(p_subject uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.subjects s join public.departments d on d.id = s.department_id
                 where s.id = p_subject and d.head_user_id = auth.uid() and d.tenant_id = public.my_tenant_id());
$$;
grant execute on function public.is_hod_of_subject(uuid) to authenticated;

/**
 * One step of the moderation workflow. Actions:
 *   submit      subject teacher / form teacher / admin: draft|returned → submitted
 *   hod_approve head of the subject's department:     submitted → hod_approved
 *   approve     school admin (principal):             submitted|hod_approved → approved
 *   return      HOD (from submitted) or admin (any step after draft): → returned, with a note
 */
create or replace function public.moderate_score_sheet(p_term uuid, p_class uuid, p_subject uuid, p_action text, p_note text default null)
returns public.score_sheets language plpgsql security definer set search_path = public as $$
declare
  t uuid := public.my_tenant_id();
  s public.score_sheets;
  teaches boolean;
  has_hod boolean;
begin
  if t is null then raise exception 'not signed in to a school'; end if;
  if not exists (select 1 from public.terms where id = p_term and tenant_id = t)
     or not exists (select 1 from public.class_groups where id = p_class and tenant_id = t)
     or not exists (select 1 from public.subjects where id = p_subject and tenant_id = t) then
    raise exception 'term, class or subject not found';
  end if;
  insert into public.score_sheets (tenant_id, term_id, class_group_id, subject_id) values (t, p_term, p_class, p_subject)
    on conflict (term_id, class_group_id, subject_id) do nothing;
  select * into s from public.score_sheets where term_id = p_term and class_group_id = p_class and subject_id = p_subject for update;

  teaches := public.is_school_admin()
    or exists (select 1 from public.subject_offerings o where o.class_group_id = p_class and o.subject_id = p_subject and o.teacher_id = auth.uid())
    or exists (select 1 from public.class_groups g where g.id = p_class and g.form_teacher_id = auth.uid());
  has_hod := exists (select 1 from public.subjects x join public.departments d on d.id = x.department_id where x.id = p_subject and d.head_user_id is not null);

  if p_action = 'submit' then
    if not teaches then raise exception 'only the subject teacher, the form teacher or an admin can submit these scores'; end if;
    if s.status not in ('draft','returned') then raise exception 'these scores are already %', replace(s.status, '_', ' '); end if;
    update public.score_sheets set status = 'submitted', submitted_by = auth.uid(), submitted_at = now(), note = null, updated_at = now() where id = s.id returning * into s;
  elsif p_action = 'hod_approve' then
    if not public.is_hod_of_subject(p_subject) then raise exception 'only the head of this subject''s department can give the first approval'; end if;
    if s.status <> 'submitted' then raise exception 'only submitted scores can be approved by the head of department'; end if;
    if s.submitted_by = auth.uid() then raise exception 'you cannot approve scores you submitted; the principal can approve them'; end if;
    update public.score_sheets set status = 'hod_approved', hod_by = auth.uid(), hod_at = now(), updated_at = now() where id = s.id returning * into s;
  elsif p_action = 'approve' then
    if not public.is_school_admin() then raise exception 'only the principal or a school admin can give final approval'; end if;
    if s.status not in ('submitted','hod_approved') then raise exception 'submit the scores before approving them'; end if;
    if s.status = 'submitted' and has_hod and coalesce(p_note, '') = '' then
      raise exception 'the head of department has not approved these scores yet; add a note to approve anyway';
    end if;
    update public.score_sheets set status = 'approved', approved_by = auth.uid(), approved_at = now(), updated_at = now() where id = s.id returning * into s;
  elsif p_action = 'return' then
    if coalesce(trim(p_note), '') = '' then raise exception 'say what needs correcting'; end if;
    if public.is_school_admin() then
      if s.status = 'draft' then raise exception 'these scores have not been submitted'; end if;
    elsif public.is_hod_of_subject(p_subject) then
      if s.status <> 'submitted' then raise exception 'the head of department can only return submitted scores'; end if;
    else
      raise exception 'only the head of department or an admin can return scores';
    end if;
    update public.score_sheets set status = 'returned', note = p_note, updated_at = now() where id = s.id returning * into s;
  else
    raise exception 'unknown action %', p_action;
  end if;
  insert into public.score_sheet_events (sheet_id, action, actor_id, note) values (s.id, p_action, auth.uid(), nullif(trim(coalesce(p_note, '')), ''));
  return s;
end $$;
revoke all on function public.moderate_score_sheet(uuid, uuid, uuid, text, text) from public;
grant execute on function public.moderate_score_sheet(uuid, uuid, uuid, text, text) to authenticated;

-- Lock scores on sheets that are under review or approved (when the school uses moderation).
create or replace function public.score_entries_moderation_lock() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  r record := coalesce(new, old);
  st text;
begin
  if auth.uid() is null or public.is_school_admin() then return coalesce(new, old); end if;
  if not coalesce((select require_moderation from public.tenant_settings where tenant_id = r.tenant_id), false) then return coalesce(new, old); end if;
  select ss.status into st from public.score_sheets ss join public.students stu on stu.id = r.student_id
    where ss.term_id = r.term_id and ss.subject_id = r.subject_id and ss.class_group_id = stu.class_group_id;
  if st in ('submitted','hod_approved','approved') then
    raise exception 'these scores are locked: they have been submitted for approval (ask the head of department or principal to return them)';
  end if;
  return coalesce(new, old);
end $$;
drop trigger if exists score_entries_moderation_lock on public.score_entries;
create trigger score_entries_moderation_lock before insert or update or delete on public.score_entries
  for each row execute function public.score_entries_moderation_lock();

-- ===== 20260101002800_report_cards_plus.sql =====
-- =========================================================================
-- EduClass Fusion: fuller report cards.
--  * Mid-term progress reports next to end-of-term cards (report_cards.kind;
--    grading_components.midterm marks which assessments count).
--  * Report templates per grading scheme: Nigerian, British, American.
--  * Cumulative (session) results shown on later terms' cards (the scheme's
--    existing cumulative_mode: 'none' turns them off).
--  * Per-subject teacher comments, effort, target and predicted grades.
--  * Comment bank for quick, consistent comments.
--  * Principal's signature and school stamp; every published card carries a
--    signature (HMAC) that the verification page checks.
-- Apply AFTER 20260101002700. Idempotent.
-- =========================================================================

alter table public.report_cards add column if not exists kind text not null default 'term';
alter table public.report_cards drop constraint if exists report_cards_kind_check;
alter table public.report_cards add constraint report_cards_kind_check check (kind in ('term','midterm'));
alter table public.report_cards drop constraint if exists report_cards_term_id_student_id_key;
drop index if exists public.report_cards_term_student_kind;
create unique index if not exists report_cards_term_student_kind on public.report_cards(term_id, student_id, kind);
alter table public.report_cards add column if not exists signature text;
alter table public.report_cards add column if not exists signed_at timestamptz;

alter table public.grading_components add column if not exists midterm boolean not null default false;
alter table public.grading_schemes add column if not exists template text not null default 'nigerian';
alter table public.grading_schemes drop constraint if exists grading_schemes_template_check;
alter table public.grading_schemes add constraint grading_schemes_template_check check (template in ('nigerian','british','american'));

alter table public.tenant_settings add column if not exists principal_signature_url text;
alter table public.tenant_settings add column if not exists stamp_url text;
alter table public.tenant_settings add column if not exists report_footer text;

create table if not exists public.report_subject_comments (
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  term_id          uuid not null references public.terms(id) on delete cascade,
  student_id       uuid not null references public.students(id) on delete cascade,
  subject_id       uuid not null references public.subjects(id) on delete cascade,
  comment          text check (char_length(comment) <= 600),
  effort           text check (char_length(effort) <= 20),
  target_grade     text check (char_length(target_grade) <= 10),
  predicted_grade  text check (char_length(predicted_grade) <= 10),
  updated_by       uuid references public.users(id) on delete set null,
  updated_at       timestamptz not null default now(),
  primary key (term_id, student_id, subject_id)
);
alter table public.report_subject_comments enable row level security;
drop policy if exists report_subject_comments_read on public.report_subject_comments;
create policy report_subject_comments_read on public.report_subject_comments for select using (
  tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists report_subject_comments_write on public.report_subject_comments;
create policy report_subject_comments_write on public.report_subject_comments for all using (
  tenant_id = public.my_tenant_id() and public.can_enter_scores(student_id, subject_id)
) with check (tenant_id = public.my_tenant_id() and public.can_enter_scores(student_id, subject_id));

create table if not exists public.comment_bank (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  role         text not null default 'form_teacher' check (role in ('form_teacher','principal','subject')),
  min_average  numeric check (min_average between 0 and 100),
  max_average  numeric check (max_average between 0 and 100),
  text         text not null check (char_length(text) between 2 and 600),
  shared       boolean not null default true,       -- visible to all staff, or only its author
  created_by   uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now()
);
alter table public.comment_bank enable row level security;
drop policy if exists comment_bank_read on public.comment_bank;
create policy comment_bank_read on public.comment_bank for select using (
  tenant_id = public.my_tenant_id() and public.is_staff() and (shared or created_by = auth.uid()));
drop policy if exists comment_bank_insert on public.comment_bank;
create policy comment_bank_insert on public.comment_bank for insert with check (
  tenant_id = public.my_tenant_id() and public.is_staff() and created_by = auth.uid());
drop policy if exists comment_bank_change on public.comment_bank;
create policy comment_bank_change on public.comment_bank for update using (
  tenant_id = public.my_tenant_id() and (created_by = auth.uid() or public.is_school_admin())) with check (tenant_id = public.my_tenant_id());
drop policy if exists comment_bank_delete on public.comment_bank;
create policy comment_bank_delete on public.comment_bank for delete using (
  tenant_id = public.my_tenant_id() and (created_by = auth.uid() or public.is_school_admin()));
